#!/bin/bash
# Portions of the code generated by Lumo and Claude

# Fail fast if variables are not set
: "${DATABASE_NAME:?DATABASE_NAME is not set}"
: "${MARIADB_BACKUP_PASSWORD:?MARIADB_BACKUP_PASSWORD is not set}"

if [ "$WEB_SERVER_TEST" != "true" ]; then
  current_date=$(date +%Y.%m.%d)
  log_file=/usr/local/logs/backup-${current_date}.log
  backup_dir=/usr/local/backups
  physical_backup=/usr/local/backups/physical-${current_date}
  logical_backup=/usr/local/backups/logical-${current_date}
  tables_order=$(cat /usr/local/DDL/000-recommended_table_order.txt)
  optimization_dir=/usr/local/backups/optimization
  maintenance_flag=/usr/local/logs/maintenance.flag
  db_maintenance_flag=/usr/local/logs/db_maintenance.flag
  # PHP log is monitored by FrankenPHP container and an email is sent if found, so we can use this for some notifications
  notify_log=/usr/local/logs/php.log
  max_parallel=3

  # Common flags shared by every MariaDB call
  common_dump_opts=(--opt --default-character-set=utf8mb4 --quote-names --single-transaction --tz-utc)

  # Timeout for pure metadata/administrative calls SQL calls
  db_admin_timeout=30

  # Multiplier applied to current datadir size to estimate free space
  disk_space_multiplier=3

  logical_name="daily"
  if [ "$(date +%u)" -eq 1 ]; then
    logical_name="weekly"
  fi
  if [ "$(date +%d)" -eq 01 ]; then
    logical_name="monthly"
  fi

  # Temporary MariaDB instance settings
  tmp_socket="/tmp/mariadb-restore.sock"
  tmp_pidfile="/tmp/mariadb-restore.pid"
  tmp_port=3307

  # Make sure target directories exist before anything tries to write
  # into them. Still before `set -e` on purpose, so we control the error
  # message rather than getting a cryptic one from the first `>>`.
  if ! mkdir -p "$(dirname "$log_file")" "$backup_dir"; then
    echo "FATAL: could not create required directories" >&2
    exit 1
  fi

  # Single-instance guard. Released automatically when the script exits for any reason, since it's tied to this fd.
  lock_file=/tmp/mariadb_backup.lock
  exec 200>"$lock_file"
  if ! flock -n 200; then
    echo "FATAL: another backup run appears to be in progress (lock: $lock_file)" >&2
    exit 1
  fi

  set -euE
  set -o pipefail

  # =========================================================
  # ERROR HANDLER
  # =========================================================
  error_handler() {
    # shellcheck disable=SC2320
    # This is fine, and the inspection gets triggered even if I explicitly save to an argument
    local exit_code=${1:-$?}
    local line=${2:-unknown}
    local timestamp
    timestamp=$(date +%Y-%m-%dT%H:%M:%S%z)
    echo "[$timestamp] Error: Command exited with code $exit_code at line $line" >> "$log_file" 2>&1
    echo "Exit code $exit_code at line $line" >> "${maintenance_flag}" 2>&1

    # Shutdown temporary MariaDB instance if still running
    if [ -f "$tmp_pidfile" ]; then
      kill "$(cat "$tmp_pidfile")" 2>/dev/null || true
      rm -f "$tmp_socket" "$tmp_pidfile"
    fi
    if [ -f "${db_maintenance_flag}" ]; then
      if ! timeout "$db_admin_timeout" mariadb --execute "UPDATE \`${DATABASE_NAME}\`.\`sys__settings\` SET \`value\` = 0 WHERE \`setting\` = 'maintenance';" >> "$log_file" 2>&1; then
        echo "[$timestamp] WARNING: failed to revert DB maintenance flag - manual intervention required" >> "$log_file" 2>&1
      fi
      rm -f "${db_maintenance_flag}"
    fi

    if [ -f "${maintenance_flag}" ]; then
      mv "${maintenance_flag}" /usr/local/logs/backup_crash.flag
    fi
    exit "$exit_code"
  }

  # =========================================================
  # LOGGING WRAPPER
  # =========================================================
  log_msg() {
    local msg="$*"
    local timestamp
    timestamp=$(date +%Y-%m-%dT%H:%M:%S%z)
    echo "[$timestamp] $msg"
  }

  # =========================================================
  # NOTIFICATION LOG
  # =========================================================
  # Flock-guarded so concurrent background jobs don't interleave writes.
  log_notify() {
    local msg="$*"
    {
      flock -x 9
      printf '%s\n' "$msg" >&9
    } 9>>"$notify_log"
  }

  # =========================================================
  # PARALLEL JOB HELPERS
  # =========================================================
  parallel_init() {
    local n="$1"
    local fifo
    fifo=$(mktemp -u)
    mkfifo "$fifo"
    exec 3<>"$fifo"
    rm -f "$fifo"
    local i
    for ((i = 0; i < n; i++)); do
      echo >&3
    done
  }

  parallel_close() {
    exec 3>&-
  }

  # Shared runner used by both the optimization phases and the table dump loop.
  run_parallel() {
    local status_file="$1"
    local -n items_ref=$2
    local worker="$3"

    parallel_init "$max_parallel"

    local item
    for item in "${items_ref[@]}"; do
      read -r -u 3
      (
        "$worker" "$item" || echo 1 >> "$status_file"
        echo >&3
      ) &
    done
    wait
    parallel_close
  }

  # =========================================================
  # DUMP TABLE DATA
  # =========================================================
  # shellcheck disable=SC2317
  # dump_table and dump_table_item are invoked indirectly via run_parallel's $worker parameter ("$worker" "$item")
  dump_table() {
    local table="$1"
    local output_file="$2"
    local rc=0

    log_msg "Backing up '$table'"
    mariadb-dump \
      --socket="$tmp_socket" \
      "${common_dump_opts[@]}" \
      --insert-ignore --no-create-info \
      --skip-log-queries \
      --databases "${DATABASE_NAME}" --tables "$table" \
      2>> "$log_file" 1>"$output_file" || rc=$?

    if [ "$rc" -eq 0 ]; then
      log_msg "Backed up '$table'"
    else
      log_msg "FAILED to back up '$table' (exit $rc)"
    fi

    return "$rc"
  }

  # Thin adapter so dump_table (2 args) fits run_parallel's one-arg worker interface.
  # shellcheck disable=SC2317
  dump_table_item() {
    local item="$1"
    local padded_idx="${item%%|*}"
    local table="${item#*|}"
    dump_table "$table" "$logical_backup/${padded_idx}-${table}.sql"
  }

  trap 'error_handler $? $LINENO' ERR
  {
    log_msg "Starting backup process"

    # =========================================================
    # RECOVER FROM A PREVIOUS RUN THAT DID NOT FINISH
    # =========================================================
    # If either flag already exists at start, the previous run was killed
    # before error_handler (or the normal completion path) ever got a
    # chance to run - e.g. the container itself crashed/restarted
    # mid-backup. Nothing about that failure was recorded or recovered at
    # the time, so check for it here before doing anything else.
    if [ -f "$maintenance_flag" ] || [ -f "$db_maintenance_flag" ]; then
      log_msg "WARNING: found leftover maintenance flag(s) from a previous run that did not complete or clean up (container crash?)"
      log_notify "[$(date +%Y-%m-%dT%H:%M:%S%z)] WARNING: backup.sh found leftover maintenance flag(s) - previous run likely did not finish; attempting recovery"

      if [ -f "$db_maintenance_flag" ]; then
        if timeout "$db_admin_timeout" mariadb --execute "UPDATE \`${DATABASE_NAME}\`.\`sys__settings\` SET \`value\` = 0 WHERE \`setting\` = 'maintenance';" >> "$log_file" 2>&1; then
          log_msg "Reverted stale DB maintenance flag"
        else
          log_msg "WARNING: failed to revert stale DB maintenance flag - manual intervention required"
          log_notify "[$(date +%Y-%m-%dT%H:%M:%S%z)] WARNING: could not revert stale DB maintenance flag automatically - manual check required"
        fi
        rm -f "$db_maintenance_flag"
      fi
      rm -f "$maintenance_flag"
    fi

    # =========================================================
    # PRE-FLIGHT CHECKS
    # =========================================================
    # A leftover temp instance from a run that didn't shut down
    # cleanly would otherwise collide with this run's. Check before
    # clean-up removes the evidence (rm -f below would hide this).
    if [ -S "$tmp_socket" ] || { [ -f "$tmp_pidfile" ] && kill -0 "$(cat "$tmp_pidfile" 2>/dev/null)" 2>/dev/null; }; then
      log_msg "ERROR: temp instance socket/pidfile already present - a previous run may not have shut down cleanly"
      error_handler 1 "$LINENO"
    fi
    if command -v ss >/dev/null 2>&1 && ss -ltn 2>/dev/null | grep -q ":$tmp_port "; then
      log_msg "ERROR: port $tmp_port is already in use"
      error_handler 1 "$LINENO"
    fi

    # Disk space precheck, before clean-up destroys the previous good backup and before maintenance mode is enabled for nothing.
    log_msg "Checking available disk space"
    db_datadir=$(timeout "$db_admin_timeout" mariadb --skip-column-names --batch --execute "SELECT @@datadir;" 2>>"$log_file") || db_datadir=""
    if [ -n "$db_datadir" ] && [ -d "$db_datadir" ]; then
      db_size_bytes=$(du -sb "$db_datadir" 2>>"$log_file" | cut -f1)
      if [ -n "$db_size_bytes" ]; then
        avail_bytes=$(df --output=avail -B1 "$backup_dir" | tail -n1 | tr -d ' ')
        required_bytes=$((db_size_bytes * disk_space_multiplier))
        log_msg "Datadir: $((db_size_bytes / 1024 / 1024)) MB, available: $((avail_bytes / 1024 / 1024)) MB, required (est.): $((required_bytes / 1024 / 1024)) MB"
        if [ "$avail_bytes" -lt "$required_bytes" ]; then
          log_msg "ERROR: insufficient disk space for backup"
          error_handler 1 "$LINENO"
        fi
      else
        log_msg "WARNING: could not determine datadir size, skipping disk space check"
      fi
    else
      log_msg "WARNING: could not determine datadir, skipping disk space check"
    fi

    touch "$maintenance_flag"
    # =========================================================
    # CLEAN-UP
    # =========================================================
    log_msg "Cleaning previous files";
    rm -rf "$backup_dir"/*.sql;
    rm -f "$tmp_socket" "$tmp_pidfile";
    # Remove physical/logical folders, and respective 7z archives. 7z archives without a folder (meaning successful compression) are preserved
    for dir in "$backup_dir"/physical-* "$backup_dir"/logical-*; do
      [ -d "$dir" ] || continue
      dir_base=$(basename "$dir")
      # strip "physical-" / "logical-" prefix
      dir_date="${dir_base#*-}"
      rm -rf "$dir"
      if [[ "$dir_base" == physical-* ]]; then
        rm -f "$backup_dir/${dir_date}-physical.7z"
      elif [[ "$dir_base" == logical-* ]]; then
        # logical_name varies (daily/weekly/monthly), so try all three
        rm -f "$backup_dir/${dir_date}-daily.7z" \
              "$backup_dir/${dir_date}-weekly.7z" \
              "$backup_dir/${dir_date}-monthly.7z"
      fi
    done

    # =========================================================
    # ENABLE MAINTENANCE
    # =========================================================
    log_msg "Enabling maintenance mode"
    timeout "$db_admin_timeout" mariadb --execute "UPDATE \`${DATABASE_NAME}\`.\`sys__settings\` SET \`value\` = 1 WHERE \`setting\` = 'maintenance';"
    touch "$db_maintenance_flag"

    # =========================================================
    # SLOW LOG
    # =========================================================
    log_msg "Processing slow log"
    mariadb << SQL_EOF
      INSERT INTO \`${DATABASE_NAME}\`.\`sys__slow_log\`
                                 (\`hash\`, \`time\`, \`length\`, \`examined\`, \`sent\`, \`text\`)
                             SELECT \`query_hash\`, \`start_time\`, \`query_time\`, \`rows_examined\`, \`rows_sent\`, \`sql_text\`
                             FROM (
                                 SELECT
                                     MD5(
                                         TRIM(
                                             /* Collapse whitespace */
                                             REGEXP_REPLACE(
                                                  /* Replace numeric literals */
                                                 REGEXP_REPLACE(
                                                    /* Replace string literals */
                                                     REGEXP_REPLACE(
                                                         \`sql_text\`,
                                                         '\'[^\']*\'', '?'
                                                     ),
                                                     '[0-9]+', '?'
                                                 ),
                                                 '[[:space:]]+', ' '
                                             )
                                         )
                                     ) AS \`query_hash\`,
                                     \`start_time\`,
                                     \`sql_text\`,
                                     \`query_time\`,
                                     \`rows_examined\`,
                                     \`rows_sent\`,
                                     ROW_NUMBER() OVER (PARTITION BY \`query_hash\` ORDER BY \`query_time\` DESC, \`start_time\` DESC) AS \`rn\`
                                 FROM \`mysql\`.\`slow_log\`
                                 WHERE \`db\` = '${DATABASE_NAME}'
                             ) AS \`ranked\`
                             WHERE \`rn\` = 1
                             ON DUPLICATE KEY UPDATE
                                  /* Use latest time value */
                                 \`time\` = IF(VALUES(\`time\`) > \`time\`, VALUES(\`time\`), \`time\`),
                                 /* For the rest use values only if the new entry has longer runtime */
                                 \`text\` = IF(VALUES(\`length\`) > \`length\`, VALUES(\`text\`), \`text\`),
                                 \`length\` = GREATEST(\`length\`, VALUES(\`length\`)),
                                 \`examined\` = IF(VALUES(\`length\`) > \`length\`, VALUES(\`examined\`), \`examined\`),
                                 \`sent\` = IF(VALUES(\`length\`) > \`length\`, VALUES(\`sent\`), \`sent\`);
                            /* Truncate original system table */
                            TRUNCATE \`mysql\`.\`slow_log\`;
                            /* Remove entries older than 3 months */
                            DELETE FROM \`${DATABASE_NAME}\`.\`sys__slow_log\` WHERE \`time\` < DATE_SUB(NOW(), INTERVAL 3 MONTH);
SQL_EOF

    # =========================================================
    # OPTIMIZATION
    # =========================================================
    execute_sql_file() {
      local sql_file="${1:-unknown}"
      local rc=0
      local output
      log_msg "Executing $sql_file"
      output=$(mariadb < "$sql_file" 2>> "$log_file") || rc=$?

      # Log the statement output to the main log same as before.
      if [ -n "$output" ]; then
        printf '%s\n' "$output" >> "$log_file"
      fi

      #If CHECK/ANALYZE/REPAIR returns a Warning row exit code is still 0.
      #Scan the tab-separated Msg_type column for Warning/error rows and forward those to the notify log without touching $rc.
      if [ -n "$output" ] && grep -qiE $'\tWarning\t|\terror\t' <<< "$output"; then
        log_notify "[$(date +%Y-%m-%dT%H:%M:%S%z)] Warning/error rows while executing $sql_file:"
        while IFS= read -r line; do
          log_notify "  $line"
        done < <(grep -iE $'\tWarning\t|\terror\t' <<< "$output")
      fi

      if [ "$rc" -eq 0 ]; then
        rm -f "$sql_file"
        log_msg "Executed $sql_file"
      else
        log_msg "FAILED executing $sql_file (exit $rc)"
      fi
      return "$rc"
    }

    optimize_sequential() {
      local phase="${1:-unknown}"
      local file="${2:-unknown}"
      if [ -f "$optimization_dir/$file" ]; then
        log_msg "Starting optimization phase $phase"
        execute_sql_file "$optimization_dir/$file" || error_handler "$?" "$LINENO"
        log_msg "Finished optimization phase $phase"
      fi
    }

    optimize_parallel() {
      local phase="${1:-unknown}"
      local directory="${2:-unknown}"

      [ -d "$optimization_dir/$directory" ] || return 0

      local -a sql_files
      mapfile -t sql_files < <(find "$optimization_dir/$directory" -maxdepth 1 -name "*.sql" -type f | sort)

      [ "${#sql_files[@]}" -gt 0 ] || return 0

      log_msg "Starting optimization phase $phase (${#sql_files[@]} files)"

      local status_file
      status_file=$(mktemp)

      run_parallel "$status_file" sql_files execute_sql_file

      local failed=0
      [ -s "$status_file" ] && failed=1
      rm -f "$status_file"

      if [ "$failed" -ne 0 ]; then
        log_msg "ERROR: One or more SQL executions failed in phase $phase"
        error_handler 1 "$LINENO"
      fi

      log_msg "Finished optimization phase $phase"
    }

    optimize_sequential 1 "01-prepare.sql"
    optimize_parallel 2 "02-common"
    optimize_sequential 3 "03-pre_optimize.sql"
    optimize_parallel 4 "04-optimize"
    optimize_sequential 5 "05-pre_fulltext.sql"
    optimize_parallel 6 "06-fulltext"
    optimize_sequential 7 "07-stats.sql"
    optimize_sequential 8 "08-reset.sql"

    # =========================================================
    # PHYSICAL BACKUP FIRST
    # =========================================================
    log_msg "Flushing logs"
    timeout "$db_admin_timeout" mariadb --execute "FLUSH LOGS;"
    log_msg "Creating physical backup"
    mariadb-backup --backup --target-dir="$physical_backup" --kill-long-queries-timeout=300 --extended-validation --lock-ddl-per-table --parallel=4
    log_msg "Preparing physical backup"
    mariadb-backup --prepare --target-dir="$physical_backup"
    log_msg "Updating ownership"
    chown mysql:mysql "$physical_backup" -R
    chmod -R +x "$physical_backup"

    # =========================================================
    # DISABLE MAINTENANCE MODE
    # =========================================================
    log_msg "Disabling maintenance mode"
    timeout "$db_admin_timeout" mariadb --execute "UPDATE \`${DATABASE_NAME}\`.\`sys__settings\` SET \`value\` = 0 WHERE \`setting\` = 'maintenance';"
    rm -f "$db_maintenance_flag"

    # =========================================================
    # START TEMP INSTANCE FROM PREPARED BACKUP
    # =========================================================
    log_msg "Starting temporary MariaDB instance"
    # Run as the mysql user so file ownership is correct
    su -s /bin/bash mysql -c \
      "mariadbd \
        --skip-log-error \
        --datadir='$physical_backup' \
        --socket='$tmp_socket' \
        --port=$tmp_port \
        --pid-file='$tmp_pidfile' \
        --skip-networking \
        --innodb-buffer-pool-size=256M \
        --innodb-flush-log-at-trx-commit=0 \
        --skip-grant-tables \
        &"

    # Wait for the temp instance to be ready
    log_msg "Waiting for temp instance to become available"
    instance_ready=0
    for _ in $(seq 1 120); do
      if mariadb --socket="$tmp_socket" --execute="SELECT 1;" &>/dev/null; then
        log_msg "Temp instance is ready"
        instance_ready=1
        break
      fi
      sleep 1
    done

    if [ "$instance_ready" -eq 0 ]; then
      log_msg "ERROR: Temp instance did not start within 120 seconds"
      error_handler 1 "$LINENO"
    fi

    log_msg "Truncating tables"
    mariadb --socket="$tmp_socket" << SQL_EOF
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`cron__log\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`seo__pageviews\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`seo__visitors\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`sys__logs\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`sys__slow_log\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`uc__cookies\`;
      TRUNCATE TABLE \`${DATABASE_NAME}\`.\`uc__sessions\`;
SQL_EOF

    # =========================================================
    # LOGICAL BACKUP FROM THE TEMP INSTANCE
    # =========================================================
    log_msg "Creating logical backup"
    mkdir -p "$logical_backup";
    log_msg "Backing up users";
    # This one needs to run on actual database due to permissions
    timeout "$db_admin_timeout" mariadb-dump \
      --all-tablespaces \
      "${common_dump_opts[@]}" \
      --add-drop-database --flush-privileges --flush-logs \
      --insert-ignore --system=users \
      2>> "$log_file" 1>> "$logical_backup/000-users.sql"
    log_msg "Backing up schema"
    timeout "$db_admin_timeout" mariadb-dump \
      --socket="$tmp_socket" \
      --all-tablespaces --no-data --skip-log-queries \
      "${common_dump_opts[@]}" \
      --add-drop-database --add-drop-trigger --flush-logs --flush-privileges \
      --routines --triggers --events \
      --databases "${DATABASE_NAME}" \
      2>> "$log_file" 1>>"$logical_backup/000-schema.sql"

    # Convert space-delimited string to array
    read -ra tables <<< "$tables_order"

    dump_items=()
    idx=0
    for table in "${tables[@]}"; do
      # Skip empty entries
      [ -z "$table" ] && continue
      idx=$((idx + 1))

      # Create zero-padded filename
      padded_idx=$(printf "%03d" "$idx")
      dump_items+=("${padded_idx}|${table}")
    done

    dump_status_file=$(mktemp)
    run_parallel "$dump_status_file" dump_items dump_table_item

    dump_failed=0
    [ -s "$dump_status_file" ] && dump_failed=1
    rm -f "$dump_status_file"

    if [ "$dump_failed" -ne 0 ]; then
      log_msg "ERROR: One or more table dumps failed"
      error_handler 1 "$LINENO"
    fi

    # =========================================================
    # SHUT DOWN TEMP INSTANCE
    # =========================================================
    log_msg "Shutting down temporary instance"
    mariadb-admin --socket="$tmp_socket" shutdown
    # Wait for clean shutdown
    shutdown_clean=0
    for _ in $(seq 1 60); do
      if [ ! -f "$tmp_pidfile" ] || ! kill -0 "$(cat "$tmp_pidfile" 2>/dev/null)" 2>/dev/null; then
        shutdown_clean=1
        break
      fi
      sleep 1
    done
    if [ "$shutdown_clean" -eq 0 ]; then
      log_msg "ERROR: temp instance did not shut down cleanly within 60 seconds"
      error_handler 1 "$LINENO"
    fi
    rm -f "$tmp_socket" "$tmp_pidfile"

    # =========================================================
    # COMPRESS BACKUPS
    # =========================================================
    log_msg "Zipping logical backup"
    7z a -aoa -y -r -stl -sdel -sse -ssp -ssw -ssc -bt -m0=LZMA2 -mhe -mtc -mta -mtm -mmt=on -p"${MARIADB_BACKUP_PASSWORD}" "$backup_dir/$current_date-${logical_name}.7z" "$logical_backup"
    rm -rf "$logical_backup";
    log_msg "Zipping physical backup"
    7z a -aoa -y -r -stl -sdel -sse -ssp -ssw -ssc -bt -m0=LZMA2 -mhe -mtc -mta -mtm -mmt=on -p"${MARIADB_BACKUP_PASSWORD}" "$backup_dir/$current_date-physical.7z" "$physical_backup"
    rm -rf "$physical_backup";
    log_msg "Backup completed"
    rm -f "$maintenance_flag"
  } >> "$log_file" 2>&1
fi
exit 0